//! 🧪️ Native physical spans and independently authored neutral remaining/refusal vectors share one original batch.
use super::*;
#[test]
fn issued_original_batch_active_spans_shrink_the_original_services_recipient_before_envelope_return(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let input=serde_json::from_value(law["input"].clone()).unwrap();let mut turn=IssuedRetainedBatch::new(input,law["envelopes"].as_u64().unwrap()as usize).unwrap();let mut source=Vec::new();let mut returned=0;
 for(index,spent)in law["spent"].as_array().unwrap().iter().enumerate(){
  let mut original=turn.envelope_recipient(index).unwrap();let progress=serde_json::from_value(spent.clone()).unwrap();let(child,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{match index{0=>{source=Vec::with_capacity(128);source.extend_from_slice("文".as_bytes());},1=>{source.extend_from_slice(&[81;9]);drop(std::mem::take(&mut source));},_=>{}}original.record_receipt(progress,law["workSpent"][index].as_u64().unwrap()).unwrap();progress});assert_eq!((heap.requested_bytes,heap.released_bytes),(child.retained_capacity_bytes,child.released_bytes));assert_eq!(serde_json::to_value(original.remaining_grant().unwrap()).unwrap(),law["activeRemaining"][index]);assert_eq!(serde_json::to_value(original.parent_remaining_input().unwrap().grant).unwrap(),law["activeRemaining"][index]);assert_eq!(original.remaining_work().unwrap().fuel,law["activeRemainingFuel"][index].as_u64().unwrap());assert_eq!(original.parent_remaining_input().unwrap().work.fuel,original.remaining_work().unwrap().fuel);
  if let Some(receipt)=original.finish().unwrap(){returned+=1;receipt.validate_for(input).unwrap();assert_eq!(serde_json::to_value(receipt.remaining).unwrap(),law["remaining"]);assert_eq!(receipt.remaining_fuel,law["remainingFuel"].as_u64().unwrap())}
 }
 assert_eq!(serde_json::to_value(returned).unwrap(),law["completionCount"]);assert_eq!(semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(source)).1.released_bytes,0);
}

#[test]
fn issued_original_batch_closed_services_recipient_cannot_checkout_or_spend_again(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let input=serde_json::from_value(law["input"].clone()).unwrap();let mut turn=IssuedRetainedBatch::new(input,1).unwrap();let mut original=turn.envelope_recipient(0).unwrap();let receipt=original.finish().unwrap().unwrap();receipt.validate_for(input).unwrap();let remaining=receipt.remaining;
 let(refused,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||(original.remaining_grant().is_err(),original.record_progress(Default::default()).is_err(),original.finish().is_err()));let expected=&law["closedRecipient"];assert_eq!(serde_json::to_value(refused).unwrap(),serde_json::json!([expected["grantRefused"],expected["recordRefused"],expected["finishRefused"]]));assert_eq!(serde_json::to_value([heap.requested_bytes,heap.released_bytes]).unwrap(),expected["heap"]);assert_eq!(serde_json::to_value(*original.original_input()==input).unwrap(),expected["sameOriginalIdentity"]);assert_eq!(receipt.remaining,remaining);assert_eq!(original.settled_progress(),Default::default());assert!(original.parent_remaining_input().is_err());
}

#[test]
fn suspended_original_batch_recipient_resumes_the_same_checkout_without_renewing_spans(){
 let suspension:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔁️resume.json")).unwrap();let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let input=serde_json::from_value(law["input"].clone()).unwrap();let mut batch=IssuedRetainedBatch::new(input,law["envelopes"].as_u64().unwrap()as usize).unwrap();let mut source=Vec::new();let mut completions=0;
 for(index,row)in law["spent"].as_array().unwrap().iter().enumerate(){
  let span=serde_json::from_value(row.clone()).unwrap();let mut original=batch.envelope_recipient(index).unwrap();let checkout=*original.original_input();
  let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{match index{0=>{source=Vec::with_capacity(128);source.extend_from_slice("文".as_bytes());},1=>{source.extend_from_slice(&[81;9]);drop(std::mem::take(&mut source));},_=>{}}original.record_receipt(span,law["workSpent"][index].as_u64().unwrap()).unwrap()});assert_eq!((heap.requested_bytes,heap.released_bytes),(span.retained_capacity_bytes,span.released_bytes));let pointer=source.as_ptr();let before=original.parent_remaining_input().unwrap();assert_eq!(semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(original)).1.requested_bytes,0);
  let(refused,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||(batch.issue_envelope(index).is_err(),batch.resume_envelope_recipient(index+1).is_err()));assert_eq!(serde_json::to_value(refused).unwrap(),serde_json::json!([suspension["duplicateIssueRefused"],suspension["wrongIndexRefused"]]));assert_eq!(serde_json::to_value([heap.requested_bytes,heap.released_bytes]).unwrap(),suspension["heap"]);assert_eq!(batch.remaining_input().unwrap(),before);
  let(resumed,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||batch.resume_envelope_recipient(index));let mut resumed=resumed.unwrap();assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(serde_json::to_value(*resumed.original_input()==checkout).unwrap(),suspension["sameCheckout"]);assert_eq!(resumed.remaining_grant().unwrap(),before.grant);assert_eq!(resumed.remaining_work().unwrap(),before.work);assert_eq!(serde_json::to_value(source.as_ptr()==pointer).unwrap(),suspension["sameSourcePointer"]);assert_eq!(serde_json::to_value(before.grant).unwrap(),law["activeRemaining"][index]);if let Some(receipt)=resumed.finish().unwrap(){completions+=1;receipt.validate_for(input).unwrap();assert_eq!(serde_json::to_value(receipt.remaining).unwrap(),law["remaining"]);assert_eq!(receipt.remaining_fuel,law["remainingFuel"].as_u64().unwrap())}
 }
 assert_eq!(serde_json::to_value(completions).unwrap(),law["completionCount"]);let(refused,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||batch.resume_envelope_recipient(0).is_err());assert_eq!(serde_json::to_value(refused).unwrap(),suspension["terminalResumeRefused"]);assert_eq!(serde_json::to_value([heap.requested_bytes,heap.released_bytes]).unwrap(),suspension["heap"]);assert_eq!(semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(source)).1.released_bytes,0);
}
